
CREATE TABLE categories(id TEXT PRIMARY KEY,name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',source TEXT,metadata_json TEXT);
CREATE TABLE product_types(id TEXT PRIMARY KEY,name TEXT NOT NULL,normalized_name TEXT NOT NULL,is_component INTEGER NOT NULL DEFAULT 0 CHECK(is_component IN(0,1)),status TEXT NOT NULL DEFAULT 'draft',source TEXT,metadata_json TEXT);
CREATE TABLE materials(id TEXT PRIMARY KEY,name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',source TEXT,metadata_json TEXT);
CREATE TABLE manufacturing_processes(id TEXT PRIMARY KEY,name TEXT NOT NULL,family TEXT,status TEXT NOT NULL DEFAULT 'draft',source TEXT,metadata_json TEXT);
CREATE TABLE taxonomy_nodes(id TEXT PRIMARY KEY,parent_id TEXT REFERENCES taxonomy_nodes(id),label TEXT NOT NULL,level INTEGER,path TEXT,source TEXT,status TEXT NOT NULL DEFAULT 'draft');
CREATE TABLE product_category_links(product_id TEXT NOT NULL REFERENCES product_types(id),category_id TEXT NOT NULL REFERENCES categories(id),role TEXT NOT NULL DEFAULT 'primary',status TEXT NOT NULL DEFAULT 'draft',confidence TEXT,source TEXT,metadata_json TEXT,PRIMARY KEY(product_id,category_id,role));
CREATE TABLE category_material_links(category_id TEXT NOT NULL REFERENCES categories(id),material_id TEXT NOT NULL REFERENCES materials(id),status TEXT NOT NULL DEFAULT 'draft',confidence TEXT,rationale TEXT,source TEXT,metadata_json TEXT,PRIMARY KEY(category_id,material_id));
CREATE TABLE category_process_links(category_id TEXT NOT NULL REFERENCES categories(id),process_id TEXT NOT NULL REFERENCES manufacturing_processes(id),status TEXT NOT NULL DEFAULT 'draft',confidence TEXT,rationale TEXT,source TEXT,metadata_json TEXT,PRIMARY KEY(category_id,process_id));
CREATE TABLE category_taxonomy_links(category_id TEXT NOT NULL REFERENCES categories(id),taxonomy_id TEXT NOT NULL REFERENCES taxonomy_nodes(id),relation_type TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',confidence TEXT,source TEXT,metadata_json TEXT,PRIMARY KEY(category_id,taxonomy_id,relation_type));
CREATE TABLE process_crosswalks(process_id TEXT NOT NULL REFERENCES manufacturing_processes(id),target_process_id TEXT NOT NULL REFERENCES manufacturing_processes(id),relation_type TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',confidence TEXT,source TEXT,metadata_json TEXT,PRIMARY KEY(process_id,target_process_id,relation_type));
CREATE TABLE taxonomy_process_links(taxonomy_id TEXT NOT NULL REFERENCES taxonomy_nodes(id),process_id TEXT NOT NULL REFERENCES manufacturing_processes(id),role TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'draft',source TEXT,metadata_json TEXT,PRIMARY KEY(taxonomy_id,process_id,role));
CREATE TABLE taxonomy_candidates(product_id TEXT NOT NULL REFERENCES product_types(id),taxonomy_id TEXT NOT NULL REFERENCES taxonomy_nodes(id),pool TEXT NOT NULL,rank INTEGER NOT NULL,lexical_score REAL CHECK(lexical_score BETWEEN 0 AND 1),status TEXT NOT NULL DEFAULT 'candidate',metadata_json TEXT,PRIMARY KEY(product_id,taxonomy_id,pool));
CREATE TABLE companies(id TEXT PRIMARY KEY,name TEXT NOT NULL,website TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE research_runs(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES companies(id),status TEXT NOT NULL DEFAULT 'pending',engine_version TEXT,started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,finished_at TEXT,metadata_json TEXT);
CREATE TABLE source_documents(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES research_runs(id),url TEXT NOT NULL,content_type TEXT,content_hash TEXT,storage_key TEXT,fetched_at TEXT,metadata_json TEXT);
CREATE TABLE evidence_records(id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES source_documents(id),excerpt TEXT NOT NULL,locator TEXT,metadata_json TEXT);
CREATE TABLE company_products(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES companies(id),run_id TEXT NOT NULL REFERENCES research_runs(id),name TEXT NOT NULL,description TEXT,status TEXT NOT NULL DEFAULT 'unverified',metadata_json TEXT);
CREATE TABLE product_classification_matches(id TEXT PRIMARY KEY,company_product_id TEXT NOT NULL REFERENCES company_products(id),product_type_id TEXT REFERENCES product_types(id),taxonomy_id TEXT REFERENCES taxonomy_nodes(id),status TEXT NOT NULL DEFAULT 'candidate',confidence REAL CHECK(confidence BETWEEN 0 AND 1),rationale TEXT,CHECK(product_type_id IS NOT NULL OR taxonomy_id IS NOT NULL));
CREATE TABLE claims(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES research_runs(id),company_product_id TEXT REFERENCES company_products(id),predicate TEXT NOT NULL,value_json TEXT NOT NULL,basis TEXT NOT NULL CHECK(basis IN('observed','inferred','unknown')),status TEXT NOT NULL DEFAULT 'unverified',confidence REAL CHECK(confidence BETWEEN 0 AND 1),rationale TEXT);
CREATE TABLE claim_evidence_links(claim_id TEXT NOT NULL REFERENCES claims(id),evidence_id TEXT NOT NULL REFERENCES evidence_records(id),relation TEXT NOT NULL DEFAULT 'supports',PRIMARY KEY(claim_id,evidence_id));
CREATE TABLE engineering_items(id TEXT PRIMARY KEY,company_product_id TEXT REFERENCES company_products(id),product_type_id TEXT REFERENCES product_types(id),name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('product','assembly','component')),metadata_json TEXT);
CREATE TABLE inference_rules(id TEXT PRIMARY KEY,name TEXT NOT NULL,version TEXT NOT NULL,rule_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',source TEXT);
CREATE TABLE item_component_links(parent_id TEXT NOT NULL REFERENCES engineering_items(id),component_id TEXT NOT NULL REFERENCES engineering_items(id),claim_id TEXT REFERENCES claims(id),rule_id TEXT REFERENCES inference_rules(id),basis TEXT NOT NULL CHECK(basis IN('observed','inferred','unknown')),status TEXT NOT NULL DEFAULT 'unverified',rationale TEXT,CHECK(parent_id<>component_id),PRIMARY KEY(parent_id,component_id));
CREATE TABLE item_material_links(item_id TEXT NOT NULL REFERENCES engineering_items(id),material_id TEXT NOT NULL REFERENCES materials(id),claim_id TEXT REFERENCES claims(id),rule_id TEXT REFERENCES inference_rules(id),basis TEXT NOT NULL CHECK(basis IN('observed','inferred','unknown')),status TEXT NOT NULL DEFAULT 'unverified',rationale TEXT,PRIMARY KEY(item_id,material_id));
CREATE TABLE item_process_links(item_id TEXT NOT NULL REFERENCES engineering_items(id),process_id TEXT NOT NULL REFERENCES manufacturing_processes(id),claim_id TEXT REFERENCES claims(id),rule_id TEXT REFERENCES inference_rules(id),basis TEXT NOT NULL CHECK(basis IN('observed','inferred','unknown')),status TEXT NOT NULL DEFAULT 'unverified',rationale TEXT,PRIMARY KEY(item_id,process_id));
CREATE TABLE validation_cases(id TEXT PRIMARY KEY,company_id TEXT REFERENCES companies(id),name TEXT NOT NULL,expected_json TEXT NOT NULL,source TEXT,status TEXT NOT NULL DEFAULT 'draft');
CREATE TABLE validation_results(id TEXT PRIMARY KEY,case_id TEXT NOT NULL REFERENCES validation_cases(id),run_id TEXT NOT NULL REFERENCES research_runs(id),metric TEXT NOT NULL,score REAL,result_json TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
